import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Publish a graphify code map with the site","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/2026-10-03-code-map-on-pages.md","filePath":"decisions/2026-10-03-code-map-on-pages.md"}`),a={name:`decisions/2026-10-03-code-map-on-pages.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="publish-a-graphify-code-map-with-the-site" tabindex="-1" dir="auto">Publish a graphify code map with the site <a class="header-anchor" href="#publish-a-graphify-code-map-with-the-site" aria-label="Permalink to “Publish a graphify code map with the site”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-10-03</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">A browsable map of the code (graphify&#39;s graph) is useful next to the site. No workflow published one before, so nothing had to be retired. The Pages source is the <code>gh-pages</code> branch (ADR 0004): <code>deploy.yml</code> replaces everything on it except <code>pr-*/</code>, so any second writer of a path would be overwritten.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li dir="auto"><code>deploy.yml</code> (push to <code>main</code> only, never on PRs) gets a first job, <code>code-map</code>: <code>pip install graphifyy==0.9.74</code> into a throwaway venv, <code>graphify extract . --code-only</code> and <code>graphify cluster-only --no-label</code> (AST only: no backend, no LLM, no API key), then <code>.github/scripts/code-map.mjs</code> writes <code>index.html</code>, <code>graph.json</code> and <code>vis-network.min.js</code> as an artifact.</li><li dir="auto">The <code>build</code> job downloads it into <code>apps/site/public/code-map/</code>, so Vite ships it and <code>pnpm pages:build</code> assembles it as part of the site. The map lands at <code>/&lt;repo&gt;/code-map/</code> through the normal deploy; there is no separate publish step.</li><li dir="auto">graphify&#39;s <code>graph.html</code> loads <code>vis-network</code> from unpkg, which the Pages artifact forbids (P1, docs/security.md). <code>code-map.mjs</code> fetches the same file from the npm tarball, checks it against the SRI hash graphify pins in the tag, and rewrites the tag to the local copy. Any other third-party asset, a missing tag or a hash mismatch fails the job.</li><li dir="auto">Third-party assets are found by parsing the HTML (jsdom) and resolving each <code>&lt;script src&gt;</code>, <code>&lt;link href&gt;</code> and <code>&lt;base href&gt;</code> with the URL parser, in <code>tools/pages/src/external-assets.mjs</code>; <code>assemble.mjs</code> and <code>code-map.mjs</code> share it. A regex over the source missed legal HTML (spaces around <code>=</code>, unquoted values, entities, <code>\\\\host</code>, <code>&lt;template&gt;</code>), and an unparsable URL counts as third-party. For that reason <code>code-map</code> also runs the workspace install, after the graph is extracted.</li><li dir="auto">graphify stays out of <code>package.json</code> and the lockfile: pip, CI only.</li><li dir="auto"><code>apps/site/public/code-map</code> is git-ignored; the folder never exists in the tree.</li><li dir="auto">The home page links to <code>code-map/</code> (&quot;מפת קוד&quot;) in a new tab.</li></ul><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">A graphify release that changes the unpkg tag breaks the job on purpose (loud failure instead of a map that loads a CDN script); review <code>code-map.mjs</code> when bumping the pinned version.</li><li dir="auto">graphify&#39;s own dependencies are not hash-pinned (only <code>graphifyy</code> is).</li><li dir="auto">PR previews have no map: the link there resolves to the production <code>404.html</code>. The preview workflow is unchanged.</li><li dir="auto">The map is built from <code>main</code> after <code>ci</code> and <code>code-map</code> both pass; a failing <code>code-map</code> job blocks the whole deploy.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};